import type { ReactElement } from 'react';

import { CatalogSummary } from '../../core/src/catalog.js';
import { StatusBadge } from '../../../../shared-ui/src/status-badge.js';
import styles from './catalog-card.module.css';

/**
 * One record, shown as a card.
 *
 * The card is pure: it is handed a summary and renders it. It fetches nothing,
 * so it names no protocol type, and its own owner carries no `dispatch`
 * classification to name one with.
 *
 * `CatalogSummary` is imported without the `type` keyword on purpose. The
 * original is an interface with no runtime binding, so this is a type-only
 * request even though the source form is an ordinary import: the summary's
 * owner never promised that anything of its runtime is browser-safe, and this
 * browser-classified view still may import the shape.
 */

export interface CatalogCardProps {
  summary: CatalogSummary;
}

/**
 * A card for one record. The badge reports whether the record has a recorded
 * history at all; it is not a review verdict, which is the neighbouring
 * panel's business.
 */
export function CatalogCard({ summary }: CatalogCardProps): ReactElement {
  const recorded = summary.revisionCount > 0;

  return (
    <article className={styles.card}>
      <h2>{summary.title}</h2>
      <StatusBadge
        status={recorded ? 'passed' : 'failed'}
        label={recorded ? 'History recorded' : 'No revisions'}
      />
      <dl className={styles.facts}>
        <dt>Record</dt>
        <dd>{summary.recordId}</dd>
        <dt>Revisions</dt>
        <dd>{summary.revisionCount}</dd>
        <dt>Latest revision</dt>
        <dd>{summary.latestRevisionId}</dd>
      </dl>
    </article>
  );
}

import type { ReactElement } from 'react';

import { StatusBadge } from '../../../../../../shared-ui/src/status-badge.js';
import { formatFinding } from './format.js';
import styles from './review-result.module.css';
import type {
  Finding,
  Observation,
  RecordId,
  ReviewStatus,
} from '../../../../../../contracts/src/interfaces/vocabulary.js';

/**
 * A finished review, rendered.
 *
 * The props are this owner's own type, written in the neutral vocabulary every
 * owner in the tree shares. That is what keeps the review runtime's own
 * `ReviewOutcome` out of the views: the outcome stops at the feature that
 * adapts it, and the connected panel above maps whatever the API answered onto
 * the shape declared here.
 */

/** What this view renders. Every member is neutral vocabulary. */
export interface ReviewResultProps {
  recordId: RecordId;
  status: ReviewStatus;
  findings: Finding[];
  observations: Observation[];
}

/** One review's verdict, its findings, and what the inspection observed. */
export function ReviewResult({
  recordId,
  status,
  findings,
  observations,
}: ReviewResultProps): ReactElement {
  return (
    <section className={styles.result}>
      <h3 className={styles.heading}>
        Review of {recordId} <StatusBadge status={status} />
      </h3>

      {findings.length === 0 ? (
        <p>No findings.</p>
      ) : (
        <ul className={styles.findings}>
          {findings.map((finding, index) => (
            <li key={`${index}-${finding.code}`}>{formatFinding(finding)}</li>
          ))}
        </ul>
      )}

      <ul className={styles.observations}>
        {observations.map((observation, index) => (
          <li key={`${index}-${observation.kind}`}>
            {observation.kind}: {observation.message}
          </li>
        ))}
      </ul>
    </section>
  );
}

